arguments.command:
curl -sS -X POST https://slack.com/api/conversations.list -H 'Authorization: Bearer <TOKEN>' --data 'types=public_channel&limit=1000' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d.get('error'), d.get('msg')); sys.exit(1)
for c in d['channels']:
    if 'launch' in c['name'].lower():
        print(c['id'], c['name'], repr(c.get('topic','')))
"

