arguments.command:
curl -sS -X POST https://slack.com/api/conversations.history -H 'Authorization: Bearer <TOKEN>' --data 'channel=C_LAUNCH&limit=200' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d.get('error'), d.get('msg')); sys.exit(1)
for m in d['messages']:
    t = m.get('text','')
    if 'checklist' in t.lower() or 'release' in t.lower():
        print(m.get('ts'), m.get('user'), json.dumps(t)[:200], '| reactions:', json.dumps(m.get('reactions', [])))
"

